<?php
require_once __DIR__ . '/includes/layout.php'; require_once __DIR__ . '/config/database.php'; checkRole(['ADMIN']); $db=getDB(); $escolinha=currentEscolinhaId(); $edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='delete'){if($id===(int)$_SESSION['user_id']){flash('error','Você não pode excluir seu próprio usuário.');}else{$db->prepare('DELETE FROM TB_USUARIO WHERE COD_USUARIO=? AND COD_ESCOLINHA=?')->execute([$id,$escolinha]);flash('success','Usuário excluído.');}go('usuarios.php');}$nome=trim($_POST['nome']??'');$email=trim($_POST['email']??'');$perfil=$_POST['perfil']??'';$senha=$_POST['senha']??'';$ativo=isset($_POST['ativo'])?1:0;if($nome===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($perfil,['ADMIN','SECRETARIA','PROFESSOR','RESPONSAVEL'],true)||($action==='create'&&strlen($senha)<6)){flash('error','Informe nome, e-mail válido, perfil e senha de ao menos 6 caracteres para um novo usuário.');go('usuarios.php'.($id?'?editar='.$id:''));}try{if($action==='create'){$db->prepare('INSERT INTO TB_USUARIO (COD_ESCOLINHA,NOME,EMAIL,SENHA_HASH,PERFIL,ATIVO) VALUES (?,?,?,?,?,?)')->execute([$escolinha,$nome,$email,password_hash($senha,PASSWORD_DEFAULT),$perfil,$ativo]);flash('success','Usuário cadastrado.');}elseif($action==='update'){if($senha!==''){$db->prepare('UPDATE TB_USUARIO SET NOME=?,EMAIL=?,PERFIL=?,ATIVO=?,SENHA_HASH=? WHERE COD_USUARIO=? AND COD_ESCOLINHA=?')->execute([$nome,$email,$perfil,$ativo,password_hash($senha,PASSWORD_DEFAULT),$id,$escolinha]);}else{$db->prepare('UPDATE TB_USUARIO SET NOME=?,EMAIL=?,PERFIL=?,ATIVO=? WHERE COD_USUARIO=? AND COD_ESCOLINHA=?')->execute([$nome,$email,$perfil,$ativo,$id,$escolinha]);}flash('success','Usuário atualizado.');}}catch(PDOException $e){flash('error','Já existe um usuário com este e-mail.');}go('usuarios.php');}
if(isset($_GET['editar'])){$q=$db->prepare('SELECT * FROM TB_USUARIO WHERE COD_USUARIO=? AND COD_ESCOLINHA=?');$q->execute([(int)$_GET['editar'],$escolinha]);$edit=$q->fetch();if(!$edit){flash('error','Usuário não encontrado.');go('usuarios.php');}}$q=$db->prepare('SELECT COD_USUARIO,NOME,EMAIL,PERFIL,ATIVO FROM TB_USUARIO WHERE COD_ESCOLINHA=? ORDER BY NOME');$q->execute([$escolinha]);$lista=$q->fetchAll();pageStart('Usuários');
?>
<section class="mb-8 rounded-xl border bg-white p-5 shadow-sm"><h2 class="mb-4 font-bold text-emerald-950"><?=$edit?'Editar usuário':'Novo usuário'?></h2><form method="post" class="grid gap-4 md:grid-cols-2"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=(int)$edit['COD_USUARIO']?>"><?php endif;?><label class="text-sm font-medium">Nome<input required name="nome" value="<?=e($edit['NOME']??'')?>" class="mt-1 w-full rounded border p-2"></label><label class="text-sm font-medium">E-mail<input required type="email" name="email" value="<?=e($edit['EMAIL']??'')?>" class="mt-1 w-full rounded border p-2"></label><label class="text-sm font-medium">Perfil<select name="perfil" class="mt-1 w-full rounded border p-2"><?php foreach(['ADMIN'=>'Administrador','SECRETARIA'=>'Secretaria','PROFESSOR'=>'Professor','RESPONSAVEL'=>'Responsável'] as $v=>$l):?><option value="<?=$v?>" <?=($edit['PERFIL']??'')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label class="text-sm font-medium">Senha <?=$edit?'(deixe vazia para manter)':''?><input <?=$edit?'':'required'?> type="password" name="senha" minlength="6" class="mt-1 w-full rounded border p-2"></label><label class="flex items-center gap-2 text-sm font-medium"><input type="checkbox" name="ativo" <?=($edit['ATIVO']??1)?'checked':''?>> Usuário ativo</label><div class="flex gap-3"><?php actionButton($edit?'Salvar alterações':'Cadastrar usuário');?><?php if($edit):?><a class="rounded-lg border px-4 py-2" href="usuarios.php">Cancelar</a><?php endif;?></div></form></section><section class="overflow-hidden rounded-xl border bg-white shadow-sm"><table class="w-full text-left text-sm"><thead class="bg-emerald-950 text-white"><tr><th class="p-3">Nome</th><th class="p-3">E-mail</th><th class="p-3">Perfil</th><th class="p-3">Estado</th><th class="p-3">Ações</th></tr></thead><tbody><?php foreach($lista as $u):?><tr class="border-t"><td class="p-3 font-medium"><?=e($u['NOME'])?></td><td class="p-3"><?=e($u['EMAIL'])?></td><td class="p-3"><?=e($u['PERFIL'])?></td><td class="p-3"><?=$u['ATIVO']?'Ativo':'Inativo'?></td><td class="flex gap-2 p-3"><a class="text-emerald-800 underline" href="usuarios.php?editar=<?=(int)$u['COD_USUARIO']?>">Editar</a><?php if($u['COD_USUARIO']!=$_SESSION['user_id']):?><form method="post" onsubmit="return confirm('Excluir este usuário?');"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$u['COD_USUARIO']?>"><button class="text-rose-700 underline">Excluir</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section><?php pageEnd();?>
